  const button = [
    { text: `\u{1F4C5} \u0412\u0456\u0434\u043A\u0440\u0438\u0442\u0438 \xAB${team.title || "\u041A\u043E\u043C\u0430\u043D\u0434\u0430"}\xBB`, url: `${siteUrl}/?team=${team.id}` }
