async function parseTelegramReminderWithAi(text, context) {
  const geminiKey = Deno.env.get("GEMINI_API_KEY") || "AIzaSyDnD6HQAJzrrxv_Nuv3BOYbXzi1Uufc_eQ";
  if (!geminiKey) {
    console.error("GEMINI_API_KEY is not configured in environment");
    return {
      status: "ERROR",
      message: "GEMINI_API_KEY \u043D\u0435 \u043D\u0430\u043B\u0430\u0448\u0442\u043E\u0432\u0430\u043D\u043E \u043D\u0430 \u0441\u0435\u0440\u0432\u0435\u0440\u0456"
    };
  }
  const promptPayload = {
    userInput: text,
    currentDateTime: context.now,
    availableCategories: context.categories || [],
    availableTemplates: context.templates || []
  };
  const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${geminiKey}`;
  const response = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      contents: [{ role: "user", parts: [{ text: JSON.stringify(promptPayload) }] }],
      systemInstruction: {
        role: "system",
        parts: [{ text: GEMINI_SYSTEM_INSTRUCTION }]
      },
      generationConfig: {
        responseMimeType: "application/json",
        responseSchema: RESPONSE_SCHEMA,
        temperature: 0.1
      }
    })
  });
  if (!response.ok) {
    const errText = await response.text();
    throw new Error(`Gemini API error ${response.status}: ${errText}`);
  }
  const geminiData = await response.json();
  const rawContent = geminiData.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!rawContent) {
    throw new Error("\u041F\u043E\u0440\u043E\u0436\u043D\u044F \u0432\u0456\u0434\u043F\u043E\u0432\u0456\u0434\u044C \u0432\u0456\u0434 Gemini API");
  }
  return JSON.parse(rawContent);
}

