async function getRemindersForRange(chatId, startIso, endIso) {
  const supabase = getSupabaseClient();
  const { data } = await supabase.from("reminders").select("*").eq("user_id", String(chatId)).gte("remind_at", startIso).lte("remind_at", endIso).order("remind_at", { ascending: true });
  return data || [];
}
function formatRemindersList(reminders, emptyMessage) {
  if (!reminders || reminders.length === 0) {
    return emptyMessage;
  }
  return reminders.map((r) => {
    const time = new Date(r.remind_at).toLocaleTimeString("uk-UA", {
      hour: "2-digit",
      minute: "2-digit",
      timeZone: "Europe/Kyiv"
    });
    const check = r.is_sent ? "\u2705" : "\u23F3";
    return `${check} <b>${time}</b> \u2014 ${escapeHtml(r.title)}`;
  }).join("\n");
}
