        const reply = `\u2728 <b>\u041D\u0430\u0433\u0430\u0434\u0443\u0432\u0430\u043D\u043D\u044F \u0437\u0430\u043F\u043B\u0430\u043D\u043E\u0432\u0430\u043D\u043E \u0447\u0435\u0440\u0435\u0437 \u0428\u0406!</b>

