  const teamId = `team_${chatId}`;
  const supabase = getSupabaseClient();
  if (!categoryRaw) {
    const helpMsg = `\u{1F4A1} <b>\u041F\u0440\u0438\u0432'\u044F\u0437\u043A\u0430 \u0442\u0435\u043C\u0438 \u0434\u043E \u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0456\u0457 \u043D\u0430\u0433\u0430\u0434\u0443\u0432\u0430\u043D\u044C:</b>

\u0412\u0432\u0435\u0434\u0456\u0442\u044C <code>/bind \u043D\u0430\u0437\u0432\u0430_\u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0456\u0457</code> \u0443 \u043F\u043E\u0442\u0440\u0456\u0431\u043D\u0456\u0439 \u0433\u0456\u043B\u0446\u0456 \u0447\u0430\u0442\u0443.

\u041D\u0430\u043F\u0440\u0438\u043A\u043B\u0430\u0434: <code>/bind \u0440\u043E\u0431\u043E\u0442\u0430</code> \u0430\u0431\u043E <code>/bind \u043D\u0430\u0432\u0447\u0430\u043D\u043D\u044F</code>.
\u041F\u0456\u0441\u043B\u044F \u0446\u044C\u043E\u0433\u043E \u0432\u0441\u0456 \u043D\u0430\u0433\u0430\u0434\u0443\u0432\u0430\u043D\u043D\u044F \u0437 \u0446\u0456\u0454\u044E \u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0456\u0454\u044E \u043D\u0430\u0434\u0441\u0438\u043B\u0430\u0442\u0438\u043C\u0443\u0442\u044C\u0441\u044F \u0441\u044E\u0434\u0438!`;
    await sendGroupMessage(botToken, chatId, helpMsg, threadId, [], incomingMessageId);
    return;
  }
  const isAdmin = await isSenderAdmin(supabase, teamId, user, botToken, chatId);
  if (!isAdmin) {
    await sendGroupMessage(
      botToken,
      chatId,
      "\u26A0\uFE0F \u0422\u0456\u043B\u044C\u043A\u0438 \u0430\u0434\u043C\u0456\u043D\u0456\u0441\u0442\u0440\u0430\u0442\u043E\u0440\u0438 \u043A\u043E\u043C\u0430\u043D\u0434\u0438 \u043C\u043E\u0436\u0443\u0442\u044C \u043F\u0440\u0438\u0432'\u044F\u0437\u0443\u0432\u0430\u0442\u0438 \u0442\u0435\u043C\u0438 \u0434\u043E \u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0456\u0439.",
      threadId,
      [],
      incomingMessageId
    );
    return;
  }
  const cleanCategory = categoryRaw.toLowerCase().replace("#", "").replace(/[^\p{L}\p{N}_-]/gu, "").slice(0, 50);
  if (!cleanCategory) {
    await sendGroupMessage(
      botToken,
      chatId,
      "\u26A0\uFE0F \u041D\u0435\u043A\u043E\u0440\u0435\u043A\u0442\u043D\u0430 \u043D\u0430\u0437\u0432\u0430 \u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0456\u0457. \u0412\u043A\u0430\u0436\u0456\u0442\u044C, \u043D\u0430\u043F\u0440\u0438\u043A\u043B\u0430\u0434: <code>/bind \u0440\u043E\u0431\u043E\u0442\u0430</code>",
      threadId,
      [],
      incomingMessageId
    );
    return;
  }
  await supabase.from("team_category_topics").upsert(
    {
      team_id: teamId,
      category: cleanCategory,
      thread_id: threadId || 0,
      updated_at: (/* @__PURE__ */ new Date()).toISOString()
    },
    { onConflict: "team_id,category" }
  );
  if (threadId) {
    await recordTopic(supabase, teamId, threadId, cleanCategory);
  }
  const targetTopicText = threadId ? "\u0446\u044E \u0442\u0435\u043C\u0443" : "\u0433\u043E\u043B\u043E\u0432\u043D\u0438\u0439 \u0447\u0430\u0442";
  const reply = `\u{1F4CC} \u041A\u0430\u0442\u0435\u0433\u043E\u0440\u0456\u044E <b>#${cleanCategory}</b> \u0443\u0441\u043F\u0456\u0448\u043D\u043E \u043F\u0440\u0438\u0432'\u044F\u0437\u0430\u043D\u043E \u0434\u043E ${targetTopicText}!

\u0422\u0435\u043F\u0435\u0440 \u0443\u0441\u0456 \u043A\u043E\u043C\u0430\u043D\u0434\u043D\u0456 \u043D\u0430\u0433\u0430\u0434\u0443\u0432\u0430\u043D\u043D\u044F \u0446\u0456\u0454\u0457 \u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0456\u0457 \u043D\u0430\u0434\u0441\u0438\u043B\u0430\u0442\u0438\u043C\u0443\u0442\u044C\u0441\u044F \u0441\u044E\u0434\u0438.`;
  await sendGroupMessage(botToken, chatId, reply, threadId, [], incomingMessageId);
}
async function handleTopicCommand(chatId, threadId, text, user, botToken, incomingMessageId) {
  if (!threadId) {
    await sendGroupMessage(
      botToken,
      chatId,
      "\u26A0\uFE0F \u0426\u044E \u043A\u043E\u043C\u0430\u043D\u0434\u0443 \u043F\u043E\u0442\u0440\u0456\u0431\u043D\u043E \u0432\u0438\u043A\u043B\u0438\u043A\u0430\u0442\u0438 \u0432\u0441\u0435\u0440\u0435\u0434\u0438\u043D\u0456 \u043A\u043E\u043D\u043A\u0440\u0435\u0442\u043D\u043E\u0457 \u0442\u0435\u043C\u0438 \u0444\u043E\u0440\u0443\u043C\u0443!",
      threadId,
      [],
      incomingMessageId
    );
    return;
  }
  const parts = text.split(/\s+/);
  parts.shift();
  const topicName = parts.join(" ").trim();
  const teamId = `team_${chatId}`;
  const supabase = getSupabaseClient();
  const isAdmin = await isSenderAdmin(supabase, teamId, user, botToken, chatId);
  if (!isAdmin) {
    await sendGroupMessage(
      botToken,
      chatId,
      "\u26A0\uFE0F \u0422\u0456\u043B\u044C\u043A\u0438 \u0430\u0434\u043C\u0456\u043D\u0456\u0441\u0442\u0440\u0430\u0442\u043E\u0440\u0438 \u043A\u043E\u043C\u0430\u043D\u0434\u0438 \u043C\u043E\u0436\u0443\u0442\u044C \u0440\u0435\u0454\u0441\u0442\u0440\u0443\u0432\u0430\u0442\u0438 \u043D\u043E\u0432\u0456 \u0442\u0435\u043C\u0438.",
      threadId,
      [],
      incomingMessageId
    );
    return;
  }
  if (!topicName) {
    await sendGroupMessage(
      botToken,
      chatId,
      "\u{1F4A1} \u0412\u043A\u0430\u0436\u0456\u0442\u044C \u043D\u0430\u0437\u0432\u0443 \u0434\u043B\u044F \u0446\u0456\u0454\u0457 \u0442\u0435\u043C\u0438:\n<code>/topic \u041D\u0430\u0437\u0432\u0430 \u0442\u0435\u043C\u0438</code>",
      threadId,
      [],
      incomingMessageId
    );
    return;
  }
  await recordTopic(supabase, teamId, threadId, topicName);
  await sendGroupMessage(
    botToken,
    chatId,
    `\u{1F3F7}\uFE0F \u0422\u0435\u043C\u0443 \u0437\u0430\u0440\u0435\u0454\u0441\u0442\u0440\u043E\u0432\u0430\u043D\u043E \u044F\u043A <b>\xAB${escapeHtml(topicName)}\xBB</b>!
\u0412\u043E\u043D\u0430 \u0432\u0436\u0435 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u0430 \u0434\u043B\u044F \u0432\u0438\u0431\u043E\u0440\u0443 \u0432 \u043A\u0430\u043B\u0435\u043D\u0434\u0430\u0440\u0456.`,
    threadId,
    [],
    incomingMessageId
  );
}

