` + (photoBytes ? `\u{1F5BC} <b>\u0421\u043A\u0440\u0456\u043D\u0448\u043E\u0442:</b> \u0434\u043E\u0434\u0430\u043D\u043E (${(photoBytes.byteLength / 1024).toFixed(1)} \u041A\u0411)
` : "") + `\u{1F194} <b>ID \u0437\u0432\u0435\u0440\u043D\u0435\u043D\u043D\u044F:</b> <code>${eventId}</code>

\u0420\u043E\u0437\u0440\u043E\u0431\u043D\u0438\u043A\u0438 \u043F\u043E\u0432\u0456\u0434\u043E\u043C\u043B\u0435\u043D\u0456 \u0442\u0430 \u0432\u0436\u0435 \u0440\u043E\u0437\u0433\u043B\u044F\u0434\u0430\u044E\u0442\u044C \u043F\u0440\u043E\u0431\u043B\u0435\u043C\u0443. \u0414\u044F\u043A\u0443\u0454\u043C\u043E!`,
        siteUrl
      );
    } else {
      console.error("Sentry feedback envelope error:", sentryRes.status, await sentryRes.text());
      await sendBotMessage(
        botToken,
        chatId,
        `\u26A0\uFE0F \u041D\u0435 \u0432\u0434\u0430\u043B\u043E\u0441\u044F \u0437\u0430\u0440\u0435\u0454\u0441\u0442\u0440\u0443\u0432\u0430\u0442\u0438 \u0437\u0432\u0456\u0442 \u0443 \u0441\u0438\u0441\u0442\u0435\u043C\u0456 Sentry. \u0421\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 \u043F\u0456\u0437\u043D\u0456\u0448\u0435.`,
        siteUrl
      );
    }
  } catch (err) {
    console.error("Failed to handle bug report:", err);
    await sendBotMessage(
      botToken,
      chatId,
      `\u26A0\uFE0F \u0421\u0442\u0430\u043B\u0430\u0441\u044F \u043F\u043E\u043C\u0438\u043B\u043A\u0430 \u043F\u0440\u0438 \u0432\u0456\u0434\u043F\u0440\u0430\u0432\u0446\u0456 \u0437\u0432\u0456\u0442\u0443. \u0421\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 \u043F\u0456\u0437\u043D\u0456\u0448\u0435.`,
      siteUrl
    );
  }
}

// supabase/functions/telegram-webhook/index.ts
Deno.serve(async (req) => {
  if (req.method !== "POST") return new Response("OK", { status: 200 });
  if (WEBHOOK_SECRET) {
    const incomingSecret = req.headers.get("x-telegram-bot-api-secret-token");
    if (incomingSecret !== WEBHOOK_SECRET) {
      console.warn("Unauthorized webhook invocation: secret token mismatch");
      return new Response(JSON.stringify({ error: "Unauthorized: invalid secret token" }), {
        status: 401,
        headers: { "Content-Type": "application/json" }
      });
    }
  }
  if (!BOT_TOKEN) {
    console.error("TELEGRAM_BOT_TOKEN is not configured in Supabase secrets");
    return new Response(JSON.stringify({ error: "TELEGRAM_BOT_TOKEN is not configured" }), {
      status: 500,
      headers: { "Content-Type": "application/json" }
    });
  }
  try {
    const update = await req.json();
    if (update?.callback_query) {
      const cq = update.callback_query;
      const chatId2 = cq.message?.chat?.id || cq.from?.id;
      if (cq.data === "get_code" && chatId2) {
        await answerCallbackQuery(BOT_TOKEN, cq.id);
        await sendAuthCode(chatId2, cq.from, BOT_TOKEN, SITE_URL);
      } else if (cq.data === "my_groups" && chatId2) {
        await answerCallbackQuery(BOT_TOKEN, cq.id);
        await handleUserGroupsCommand(chatId2, BOT_TOKEN, SITE_URL);
      } else if (cq.data.startsWith("done_")) {
        const reminderId = cq.data.replace("done_", "");
        const supabase = getSupabaseClient();
        await supabase.from("reminders").update({ is_sent: true }).eq("id", reminderId);
        await answerCallbackQuery(BOT_TOKEN, cq.id, "\u2705 \u041D\u0430\u0433\u0430\u0434\u0443\u0432\u0430\u043D\u043D\u044F \u0432\u0438\u043A\u043E\u043D\u0430\u043D\u043E!");
        if (cq.message?.chat?.id && cq.message?.message_id) {
          await deleteTelegramMessage(BOT_TOKEN, cq.message.chat.id, cq.message.message_id);
        }
      } else if (cq.data.startsWith("snooze_")) {
        const reminderId = cq.data.replace("snooze_", "");
        const supabase = getSupabaseClient();
        const snoozeDate = new Date(Date.now() + 15 * 60 * 1e3).toISOString();
        await supabase.from("reminders").update({ remind_at: snoozeDate, is_sent: false }).eq("id", reminderId);
        await answerCallbackQuery(BOT_TOKEN, cq.id, "\u{1F4A4} \u0412\u0456\u0434\u043A\u043B\u0430\u0434\u0435\u043D\u043E \u043D\u0430 15 \u0445\u0432!");
      } else if (cq.data.startsWith("cancel_")) {
        const reminderId = cq.data.replace("cancel_", "");
        const supabase = getSupabaseClient();
        await supabase.from("reminders").delete().eq("id", reminderId).eq("user_id", String(chatId2));
        await answerCallbackQuery(BOT_TOKEN, cq.id, "\u{1F5D1} \u041D\u0430\u0433\u0430\u0434\u0443\u0432\u0430\u043D\u043D\u044F \u0441\u043A\u0430\u0441\u043E\u0432\u0430\u043D\u043E!");
        if (cq.message?.chat?.id && cq.message?.message_id) {
          await editTelegramMessage(
            BOT_TOKEN,
            cq.message.chat.id,
            cq.message.message_id,
            "\u274C <i>\u041D\u0430\u0433\u0430\u0434\u0443\u0432\u0430\u043D\u043D\u044F \u0431\u0443\u043B\u043E \u0443\u0441\u043F\u0456\u0448\u043D\u043E \u0441\u043A\u0430\u0441\u043E\u0432\u0430\u043D\u043E.</i>"
          );
        }
      } else {
        await answerCallbackQuery(BOT_TOKEN, cq.id);
      }
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    }
    if (update?.chat_member) {
      const cm = update.chat_member;
      const chat = cm.chat;
      const isGroup = chat?.type === "group" || chat?.type === "supergroup";
      if (isGroup && cm.new_chat_member?.user && !cm.new_chat_member.user.is_bot) {
        const supabase = getSupabaseClient();
        const teamId = await ensureTeamExists(supabase, chat, cm.from?.id);
        const status = cm.new_chat_member.status;
        if (status === "member" || status === "administrator" || status === "creator") {
          await recordTeamMember(
            supabase,
            teamId,
            cm.new_chat_member.user,
            status === "administrator" || status === "creator"
          );
        }
      }
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    }
    if (update?.my_chat_member) {
      const mcm = update.my_chat_member;
      const chat = mcm.chat;
      const isGroup = chat?.type === "group" || chat?.type === "supergroup";
      if (isGroup) {
        await handleMyChatMemberUpdate(mcm, BOT_TOKEN, SITE_URL);
      }
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    }
    const message = update?.message;
    if (!message || !message.chat) return new Response("OK", { status: 200 });
    const chatId = message.chat.id;
    const chatType = message.chat.type;
    const isGroupChat = chatType === "group" || chatType === "supergroup";
    const text = (message.text || "").trim();
    const lowerText = text.toLowerCase();
    const threadId = message.message_thread_id;
    if (isGroupChat) {
      const supabase = getSupabaseClient();
      if (message.migrate_to_chat_id) {
        const oldTeamId = `team_${chatId}`;
        const newTeamId = `team_${message.migrate_to_chat_id}`;
        await supabase.from("team_members").update({ team_id: newTeamId }).eq("team_id", oldTeamId);
        await supabase.from("reminders").update({ team_id: newTeamId }).eq("team_id", oldTeamId);
        await supabase.from("team_categories").update({ team_id: newTeamId }).eq("team_id", oldTeamId);
        await supabase.from("team_topics").update({ team_id: newTeamId }).eq("team_id", oldTeamId);
        await supabase.from("team_category_topics").update({ team_id: newTeamId }).eq("team_id", oldTeamId);
        await supabase.from("teams").delete().eq("id", oldTeamId);
        return new Response(JSON.stringify({ ok: true }), {
          status: 200,
          headers: { "Content-Type": "application/json" }
        });
      }
      const teamId = await ensureTeamExists(supabase, message.chat, message.from?.id);
      if (message.from && !message.from.is_bot) {
        await recordTeamMember(supabase, teamId, message.from);
      }
      if (Array.isArray(message.new_chat_members)) {
        for (const nm of message.new_chat_members) {
          if (!nm.is_bot) {
            await recordTeamMember(supabase, teamId, nm);
          }
        }
      }
      if (message.forum_topic_created) {
        await recordTopic(supabase, teamId, threadId, message.forum_topic_created.name);
      } else if (threadId) {
        await recordTopic(supabase, teamId, threadId, "");
      }
      if (lowerText.startsWith("/bind")) {
        await handleBindCommand(chatId, threadId, text, message.from, BOT_TOKEN, message.message_id);
        return new Response(JSON.stringify({ ok: true }), {
          status: 200,
          headers: { "Content-Type": "application/json" }
        });
      }
      if (lowerText.startsWith("/topic")) {
        await handleTopicCommand(chatId, threadId, text, message.from, BOT_TOKEN, message.message_id);
        return new Response(JSON.stringify({ ok: true }), {
          status: 200,
          headers: { "Content-Type": "application/json" }
        });
      }
      if (lowerText.startsWith("/sync")) {
        await handleSyncCommand(chatId, threadId, message.chat, BOT_TOKEN, SITE_URL, message.message_id);
        return new Response(JSON.stringify({ ok: true }), {
          status: 200,
          headers: { "Content-Type": "application/json" }
        });
      }
      if (lowerText.startsWith("/addmember") || lowerText.startsWith("/\u0434\u043E\u0434\u0430\u0442\u0438")) {
        await handleAddMemberCommand(chatId, threadId, text, message.from, BOT_TOKEN, message.message_id);
        return new Response(JSON.stringify({ ok: true }), {
          status: 200,
          headers: { "Content-Type": "application/json" }
        });
      }
      if (lowerText.startsWith("/team") || lowerText.startsWith("/calendar") || lowerText.startsWith("/\u043A\u0430\u043B\u0435\u043D\u0434\u0430\u0440")) {
        await handleTeamCommand(chatId, threadId, BOT_TOKEN, SITE_URL, message.message_id);
        return new Response(JSON.stringify({ ok: true }), {
          status: 200,
          headers: { "Content-Type": "application/json" }
        });
      }
      if (lowerText.startsWith("/groups") || lowerText.startsWith("/\u0433\u0440\u0443\u043F\u0438")) {
        const botStatus = await getBotChatStatus(BOT_TOKEN, chatId);
        const statusBadge = botStatus.isAdmin ? `\u2705 <b>\u0410\u0434\u043C\u0456\u043D\u0456\u0441\u0442\u0440\u0430\u0442\u043E\u0440</b> (\u043F\u043E\u0432\u043D\u0438\u0439 \u0434\u043E\u0441\u0442\u0443\u043F \u0434\u043E \u0442\u0435\u043C)` : `\u26A0\uFE0F <b>\u0417\u0432\u0438\u0447\u0430\u0439\u043D\u0438\u0439 \u0443\u0447\u0430\u0441\u043D\u0438\u043A</b> (\u043F\u0440\u0438\u0437\u043D\u0430\u0447\u0442\u0435 \u0430\u0434\u043C\u0456\u043D\u043E\u043C \u0434\u043B\u044F \u0434\u043E\u0441\u0442\u0443\u043F\u0443 \u0434\u043E \u0442\u0435\u043C!)`;
        const reply = `\u2139\uFE0F <b>\u0421\u0442\u0430\u0442\u0443\u0441 \u0431\u043E\u0442\u0430 \u0432 \u0446\u044C\u043E\u043C\u0443 \u0447\u0430\u0442\u0456:</b> ${statusBadge}

\u{1F4CB} \u0429\u043E\u0431 \u043F\u0435\u0440\u0435\u0433\u043B\u044F\u043D\u0443\u0442\u0438 <b>\u0432\u0441\u0456 \u0432\u0430\u0448\u0456 \u043F\u0456\u0434\u043A\u043B\u044E\u0447\u0435\u043D\u0456 \u0433\u0440\u0443\u043F\u0438</b>, \u043F\u0435\u0440\u0435\u0439\u0434\u0456\u0442\u044C \u0432 \u043E\u0441\u043E\u0431\u0438\u0441\u0442\u0456 \u043F\u043E\u0432\u0456\u0434\u043E\u043C\u043B\u0435\u043D\u043D\u044F \u0437 \u0431\u043E\u0442\u043E\u043C:`;
        const keyboard = [
          [{ text: "\u{1F4AC} \u041F\u0435\u0440\u0435\u0433\u043B\u044F\u043D\u0443\u0442\u0438 \u0432\u0441\u0456 \u043C\u043E\u0457 \u0433\u0440\u0443\u043F\u0438", url: `https://t.me/reminderveter_bot?start=groups` }]
        ];
        await sendGroupMessage(BOT_TOKEN, chatId, reply, threadId, keyboard, message.message_id);
        return new Response(JSON.stringify({ ok: true }), {
          status: 200,
          headers: { "Content-Type": "application/json" }
        });
      }
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    }
    const isBugReport = lowerText.startsWith("/bug") || lowerText.startsWith("/feedback") || lowerText.startsWith("/\u043F\u043E\u043C\u0438\u043B\u043A\u0430") || lowerText.startsWith("/\u0432\u0456\u0434\u0433\u0443\u043A") || lowerText === "\u0431\u0430\u0433" || lowerText === "\u0432\u0456\u0434\u0433\u0443\u043A" || message.photo && (lowerText.includes("\u0431\u0430\u0433") || lowerText.includes("\u043F\u043E\u043C\u0438\u043B\u043A\u0430") || lowerText.includes("\u0432\u0456\u0434\u0433\u0443\u043A") || lowerText.includes("bug") || lowerText.includes("feedback") || lowerText.startsWith("/bug"));
    if (isBugReport) {
      await handleBugReportCommand(chatId, message, BOT_TOKEN, SITE_URL);
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    }
    const isCodeRequest = lowerText.startsWith("/code") || lowerText.startsWith("/login") || lowerText.startsWith("/start login") || lowerText.startsWith("/start code") || lowerText === "\u043A\u043E\u0434" || text === "\u{1F511} \u041A\u043E\u0434 \u0434\u043B\u044F \u0432\u0445\u043E\u0434\u0443";
    if (isCodeRequest) {
      await sendAuthCode(chatId, message.from, BOT_TOKEN, SITE_URL);
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    }
    const isGroupsRequest = lowerText.startsWith("/groups") || lowerText.startsWith("/teams") || lowerText.startsWith("/\u0433\u0440\u0443\u043F\u0438") || lowerText.startsWith("/\u043A\u043E\u043C\u0430\u043D\u0434\u0438") || lowerText.startsWith("/start groups") || lowerText === "\u0433\u0440\u0443\u043F\u0438" || lowerText === "\u043A\u043E\u043C\u0430\u043D\u0434\u0438" || lowerText === "\u043C\u043E\u0457 \u0433\u0440\u0443\u043F\u0438" || text === "\u{1F465} \u041C\u043E\u0457 \u0433\u0440\u0443\u043F\u0438 \u0442\u0430 \u0441\u0442\u0430\u0442\u0443\u0441 \u0431\u043E\u0442\u0430";
    if (isGroupsRequest) {
      await handleUserGroupsCommand(chatId, BOT_TOKEN, SITE_URL);
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    }
    if (lowerText === "/today" || lowerText === "/\u0441\u044C\u043E\u0433\u043E\u0434\u043D\u0456" || lowerText === "\u0441\u044C\u043E\u0433\u043E\u0434\u043D\u0456") {
      await handleTodayCommand(chatId, BOT_TOKEN, SITE_URL);
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    }
    if (lowerText === "/tomorrow" || lowerText === "/\u0437\u0430\u0432\u0442\u0440\u0430" || lowerText === "\u0437\u0430\u0432\u0442\u0440\u0430") {
      await handleTomorrowCommand(chatId, BOT_TOKEN, SITE_URL);
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    }
    if (lowerText === "/week" || lowerText === "/\u0442\u0438\u0436\u0434\u0435\u043D\u044C" || lowerText === "\u0442\u0438\u0436\u0434\u0435\u043D\u044C") {
      await handleWeekCommand(chatId, BOT_TOKEN, SITE_URL);
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    }
    if (lowerText === "/help" || lowerText === "/\u0434\u043E\u0432\u0456\u0434\u043A\u0430" || lowerText === "\u0434\u043E\u043F\u043E\u043C\u043E\u0433\u0430") {
      await sendHelp(chatId, BOT_TOKEN, SITE_URL);
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    }
    if (text) {
      await handleAiReminderMessage(chatId, text, message.from, BOT_TOKEN, SITE_URL);
    } else if (message.photo && message.photo.length > 0) {
      await handleBugReportCommand(chatId, message, BOT_TOKEN, SITE_URL);
    } else {
      await sendWelcome(chatId, message.from, BOT_TOKEN, SITE_URL);
    }
    return new Response(JSON.stringify({ ok: true }), {
      status: 200,
      headers: { "Content-Type": "application/json" }
    });
  } catch (err) {
    console.error("Webhook error:", err);
    return new Response("OK", { status: 200 });
  }
});
